// Идемпотентность + сборка поста VK
const row = $input.first().json;
if (!row || !row.id) throw new Error('Publication not found or already processed');
if (row.external_post_id) return [{ json: { ...row, skip: true } }];
if (!row.secret_ref) throw new Error('No integration connection / secret_ref for channel');
if (!row.external_channel_id) throw new Error('external_channel_id (owner_id) is required for VK');

// owner_id: для сообщества — отрицательный id (-123456)
let ownerId = String(row.external_channel_id).trim();
if (/^\d+$/.test(ownerId)) ownerId = '-' + ownerId; // ввели голый id группы

const message = [row.body, (row.hashtags ?? []).map(h => `#${h}`).join(' ')]
  .filter(Boolean).join('\n\n');
if (!message) throw new Error('Empty message');

return [{ json: { ...row, owner_id: ownerId, message, skip: false } }];

// VK возвращает 200 даже при ошибке — проверяем поле error
const res = $input.first().json;
if (res.error) {
  throw new Error(`VK API error ${res.error.error_code}: ${res.error.error_msg}`);
}
const postId = res.response?.post_id;
if (!postId) throw new Error('VK: post_id отсутствует в ответе');
const ownerId = $('Idempotency Guard + Build Post').item.json.owner_id;
return [{ json: {
  post_id: String(postId),
  post_url: `https://vk.com/wall${ownerId}_${postId}`,
} }];
